-- Verify that typical SQL rows with large TEXT columns store inline (no overflow)
-- and that very large values survive a round-trip through overflow pages.
-- CHUNK_THRESHOLD = 1005 bytes, so rows < 1005 bytes are fully inline.

CREATE TABLE docs (id INTEGER, body TEXT)
-- > Table 'docs' created

-- ~500-char TEXT value: well under CHUNK_THRESHOLD, should store inline
INSERT INTO docs VALUES (1, '')
-- > 1

SELECT id, body FROM docs WHERE id = 1
-- > 1, ""

-- ~2000-char TEXT value: exceeds CHUNK_THRESHOLD, uses overflow pages
INSERT INTO docs VALUES (2, '')
-- > 1

SELECT id FROM docs WHERE id = 2
-- > 2
